--
-- Table structure for table `families`
--

DROP TABLE IF EXISTS `families`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `families` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL COMMENT '创建者ID',
  `surname` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓氏',
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '谱名',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '简介',
  `origin` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '发源地/籍贯',
  `generation_start` int(11) DEFAULT '1' COMMENT '起始世次',
  `cover_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '封面图',
  `is_public` tinyint(4) DEFAULT '0' COMMENT '1公开 0私密',
  `tree_layout` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'horizontal' COMMENT '世系图布局',
  `share_token` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分享令牌',
  `status` tinyint(4) DEFAULT '1' COMMENT '1正常 0删除',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_surname` (`surname`),
  KEY `idx_is_public` (`is_public`),
  KEY `idx_status` (`status`),
  KEY `idx_share_token` (`share_token`),
  CONSTRAINT `families_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='家谱表';
