INSERT INTO `families` VALUES (1,2,'王','王芦庄','','河北省沧州市沧县',1,'uploads/covers/cover_56b7f8479f9fe0a6d7f2dd09a549b051_1781424531.png',1,'vertical',NULL,0,'2026-06-14 12:55:05','2026-06-14 16:41:55'),(2,2,'杨','沧州杨氏','','河北省沧州市运河区',1,'uploads/covers/cover_7ca3a6c657e730fe071ca71c689b9408_1781416701.png',0,'horizontal',NULL,0,'2026-06-14 13:58:21','2026-06-14 13:59:45'),(3,2,'杨','杨氏家谱','','山西省阳泉市郊区',1,'uploads/covers/cover_4e23d9d5205e31be3c7baa7c19a9c0ac_1781422649.png',1,'horizontal','d2f9052c83b320e1f00201ebe768c1fe',0,'2026-06-14 15:37:13','2026-06-14 18:12:42'),(4,2,'李','西河头','','河北省沧州市沧县',1,'uploads/covers/cover_a6ed108e5306e9cfe6ac87f8ef50cedb_1781425868.png',0,'vertical',NULL,0,'2026-06-14 16:31:08','2026-06-14 18:12:50'),(5,2,'王','王氏家族','','河北省沧州市沧县',1,'uploads/covers/cover_9a99bf78646eb0c9610d72a0ab26bc04_1781426544.png',1,'horizontal',NULL,0,'2026-06-14 16:42:24','2026-06-14 18:12:35'),(6,2,'张','张氏家族','','河北省张家口市怀安县',1,'uploads/covers/cover_96a780933d4bfe3d22f7092e8058be02_1781432176.png',1,'vertical',NULL,1,'2026-06-14 18:16:16','2026-06-29 23:05:37'),(7,2,'刘','刘氏家族','','浙江省嘉兴市海盐县',1,'uploads/covers/cover_6008fd2f1777158ffd4cd189ced26005_1781433479.png',0,'vertical',NULL,1,'2026-06-14 18:37:59','2026-06-14 18:38:05'),(8,2,'王','王芦庄','','安徽省铜陵市郊区',1,'uploads/covers/cover_68a70027136054ba09a77c410b5f96a8_1781433656.png',1,'horizontal',NULL,1,'2026-06-14 18:40:56','2026-06-29 23:05:28'),(9,2,'孙','小王庄','','内蒙古自治区赤峰市阿鲁科尔沁旗',1,'uploads/covers/cover_1aceefe2fea6d41969ee7f943cce0e9a_1781434435.png',0,'horizontal',NULL,0,'2026-06-14 18:53:55','2026-06-30 23:58:06'),(10,2,'孙','小王庄','','内蒙古自治区赤峰市阿鲁科尔沁旗',1,'uploads/covers/cover_1aceefe2fea6d41969ee7f943cce0e9a_1781434949.png',0,'vertical',NULL,0,'2026-06-14 19:02:29','2026-06-30 23:58:09'),(11,2,'周','周氏家族','','河北省秦皇岛市北戴河区',1,'uploads/covers/cover_32e26ec65a386dead161a86166735bbf_1781434984.png',0,'horizontal',NULL,0,'2026-06-14 19:03:04','2026-06-30 23:58:14'),(12,4,'王','王氏家谱','','内蒙古自治区包头市昆都仑区',1,'uploads/covers/cover_3a1f58ee7af07cfebcd5e348a7e93a91_1782745780.png',0,'horizontal',NULL,0,'2026-06-29 23:09:41','2026-06-30 23:58:12'),(13,1,'沧县王芦庄','王氏家谱','','河北省沧州市沧县',1,'uploads/covers/cover_ff1ea132a2eadeadc7459a4a4ced11ba_1782816238.png',0,'horizontal',NULL,0,'2026-06-30 18:43:58','2026-06-30 18:44:46'),(14,1,'王','沧县王芦庄','','河北省沧州市沧县',1,'uploads/covers/cover_d3cbe0f2e24fa0f556f57a5ba3722a32_1782835122.png',0,'horizontal',NULL,1,'2026-06-30 18:45:17','2026-06-30 23:58:42'),(15,5,'杨','泾川飞云杨氏族谱','泾川杨姓最早是神话传说中的西王母。关于西王母的姓⽒，《⾣阳杂俎·诺皋记》上卷记载：西王母姓杨名回，负责治理昆仑⼭西北部。《通雅·姓名》⾥也有记载，也提到了西王母的姓⽒就是杨。王母宫⼭也叫回⼭，312国道叫回中道，都以杨回的名字命名。泾川杨⽒是明洪武年间由⼭西省洪洞县铁涝池迁来的。县域内有荔堡⼤寨杨家、丰台杨涝池杨家、党原东联杨家、太平杨家、飞云站背后杨家、泾明⼭底下杨家以及窑店公主杨家、练范杨家、西杨家。⽽西门官路、南头湾鲁家⼭杨家则都是西杨家的分⽀，则因地理位置的划分，⽽分属到了不同的⾏政区划之内。泾川还有⼀⽀杨姓族⼈，过了泾河，向北迁⾄庆阳市正宁县罗川康家沟⼀带。','甘肃省平凉市泾川县',1,'uploads/covers/cover_df336dc7f3689777ac6231e578df6e21_1782833261.png',1,'vertical',NULL,1,'2026-06-30 23:27:41','2026-07-02 22:00:04'),(16,6,'张','张的族谱','','江苏省南京市江宁区',1,'uploads/covers/cover_7fd1dbaef59136f5941cc925a245925c_1783145061.png',0,'horizontal',NULL,1,'2026-07-04 14:04:21','2026-07-04 14:04:21'),(17,7,'王','王芦庄家谱','','河北省沧州市沧县',1,'uploads/covers/cover_31ca6d179c3dc37c729b4bcc7b677512_1783989491.png',0,'horizontal',NULL,1,'2026-07-14 08:38:11','2026-07-14 08:38:11');
