--
-- Table structure for table `members`
--

DROP TABLE IF EXISTS `members`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `members` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `family_id` int(10) unsigned NOT NULL COMMENT '家谱ID',
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `gender` enum('male','female','unknown') COLLATE utf8mb4_unicode_ci DEFAULT 'unknown' COMMENT '性别',
  `birth_date` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '出生日期',
  `death_date` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '逝世日期',
  `generation` int(11) DEFAULT '1' COMMENT '世次',
  `biography` text COLLATE utf8mb4_unicode_ci COMMENT '生平简介',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '头像',
  `parent_id` int(10) unsigned DEFAULT NULL COMMENT '父/母节点ID',
  `spouse_id` int(10) unsigned DEFAULT NULL COMMENT '配偶ID',
  `sort_order` int(11) DEFAULT '0' COMMENT '排序',
  `status` tinyint(4) DEFAULT '1' COMMENT '1正常 0删除',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_family_id` (`family_id`),
  KEY `idx_parent_id` (`parent_id`),
  KEY `idx_generation` (`generation`),
  KEY `idx_sort_order` (`sort_order`),
  KEY `idx_status` (`status`),
  CONSTRAINT `members_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=431 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='家族成员表';
/*!40101 SET character_set_client = @saved_cs_client */;

