INSERT INTO `site_settings` VALUES (1,'site_name','族谱传承','2026-06-13 23:28:49','2026-06-13 23:28:49'),(2,'site_subtitle','寻根溯源 传承家风','2026-06-13 23:28:49','2026-06-13 23:28:49'),(3,'site_keywords','家谱,族谱,修谱,家族,传承','2026-06-13 23:28:49','2026-06-13 23:28:49'),(4,'site_description','专业的家谱管理平台，帮助您记录和传承家族历史','2026-06-13 23:28:49','2026-06-13 23:28:49'),(5,'site_icp','冀ICP备2026006497号','2026-06-13 23:28:49','2026-06-14 13:25:38'),(6,'site_footer','族谱传承 家谱管理系统','2026-06-13 23:28:49','2026-06-13 23:28:49'),(7,'allow_register','1','2026-06-13 23:28:49','2026-06-13 23:28:49'),(8,'logo_text','族','2026-06-13 23:28:49','2026-06-13 23:28:49'),(9,'primary_color','#8b4513','2026-06-13 23:28:49','2026-06-14 13:25:38'),(10,'captcha_enabled','0','2026-06-14 12:42:03','2026-06-14 20:58:09'),(11,'print_header','','2026-06-14 13:26:10','2026-06-14 13:26:10'),(12,'about_info','传承家族历史，弘扬优良家风','2026-06-14 13:26:10','2026-06-14 13:26:10'),(13,'hero_title','家之有谱 犹国之有史也','2026-06-14 13:30:05','2026-06-14 13:30:05'),(14,'hero_subtitle','传承中华文化，弘扬优良家风，让每一段家族记忆都得以永续流传','2026-06-14 13:30:05','2026-06-14 13:30:05'),(15,'hero_search_placeholder','搜索姓氏或家谱名称...','2026-06-14 13:30:05','2026-06-14 13:30:05'),(16,'about_title','关于族谱传承','2026-06-14 13:30:05','2026-06-14 13:30:05'),(17,'about_content','族谱，又称家谱、宗谱，是记载一个家族世系繁衍及重要人物事迹的特殊文献。中国家谱文化源远流长，博大精深，与国史、方志并称为中国历史的三大支柱。\r\n\r\n宋代以后，修谱之风从官方流入民间，私家修谱蔚然成风。一本本家谱，承载着一个家族的血脉传承，记录了先辈们的艰辛与荣耀，连接着过去与未来。\r\n\r\n我们希望通过数字化方式，让家谱文化在新时代焕发新的生机，帮助更多人寻根溯源，了解自己的家族历史。','2026-06-14 13:30:05','2026-06-14 20:02:15'),(18,'feature1_icon','assets/images/pedigree.png','2026-06-14 13:30:05','2026-06-14 13:57:53'),(19,'feature1_title','谱牒','2026-06-14 13:30:05','2026-06-14 13:30:05'),(20,'feature1_desc','在线创建和管理家族谱系，支持多世代录入与编辑','2026-06-14 13:30:05','2026-06-14 13:30:05'),(21,'feature2_icon','assets/images/surname.png','2026-06-14 13:30:05','2026-06-14 13:57:53'),(22,'feature2_title','姓氏','2026-06-14 13:30:05','2026-06-14 13:30:05'),(23,'feature2_desc','按姓氏搜索和浏览家谱，寻找同宗同源','2026-06-14 13:30:05','2026-06-14 13:30:05'),(24,'feature3_icon','assets/images/encyclopedia.png','2026-06-14 13:30:05','2026-06-14 13:57:53'),(25,'feature3_title','百科','2026-06-14 13:30:05','2026-06-14 13:30:05'),(26,'feature3_desc','丰富的姓氏起源与家族文化知识库','2026-06-14 13:30:05','2026-06-14 13:30:05'),(27,'feature4_icon','assets/images/space.png','2026-06-14 13:30:05','2026-06-14 13:57:53'),(28,'feature4_title','空间','2026-06-14 13:30:05','2026-06-14 13:30:05'),(29,'feature4_desc','创建私密家族空间，与亲友共同维护家谱','2026-06-14 13:30:05','2026-06-14 13:30:05'),(30,'agreement_content','<h3>一、总则</h3>\r\n<p>欢迎您使用族谱传承。在您注册成为本系统用户之前，请务必仔细阅读本协议。一旦您完成注册，即表示您已充分理解并同意本协议的全部条款。</p>\r\n<h3>二、账号注册与管理</h3>\r\n<p>1. 您在注册时应提供真实、准确的个人信息，包括但不限于用户名、邮箱地址等。</p>\r\n<p>2. 您应妥善保管账号和密码，因账号泄露导致的损失由您自行承担。</p>\r\n<p>3. 每个用户只能注册一个账号，禁止利用本系统进行任何非法活动。</p>\r\n<h3>三、隐私保护</h3>\r\n<p>我们高度重视您的隐私保护。除法律法规要求外，我们不会向第三方提供您的个人信息。</p>\r\n<h3>四、免责声明</h3>\r\n<p>1. 因网络故障、系统维护、自然灾害等不可抗力导致的损失，本系统不承担责任。</p>\r\n<p>2. 用户之间因使用本系统产生的纠纷，由双方自行协商解决。</p>','2026-06-14 13:45:48','2026-06-14 20:02:15'),(31,'privacy_content','<h3>一、信息收集</h3>\r\n<p>当您注册和使用本系统时，我们可能收集以下信息：账号信息（用户名、邮箱地址、加密密码）、使用数据（登录时间、操作日志、IP地址）、家谱数据。</p>\r\n<h3>二、信息使用</h3>\r\n<p>收集的信息仅用于：提供和维护本系统服务、用户身份验证与安全保障、回复用户咨询。</p>\r\n<h3>三、信息安全</h3>\r\n<p>1. 用户密码使用 bcrypt 加密存储，任何人无法获取原始密码。</p>\r\n<p>2. 系统采用数据库安全防护措施，防止未授权访问和数据泄露。</p>\r\n<h3>四、信息共享</h3>\r\n<p>我们不会将您的个人信息出售、出租或共享给第三方，除非：获得您的明确同意、法律法规或司法机关要求。</p>','2026-06-14 13:45:48','2026-06-14 20:02:15'),(32,'home_hero_title','承千年文脈，续家族荣光','2026-06-14 19:35:55','2026-06-14 21:17:09'),(33,'home_hero_subtitle','数字化修谱平台，让每一段家族记忆都熠熠生辉','2026-06-14 19:35:55','2026-06-14 21:17:09'),(34,'home_hero_bg','','2026-06-14 19:35:55','2026-06-14 19:35:55'),(35,'home_hero_bg_overlay','rgba(20,15,10,0.50)','2026-06-14 19:35:55','2026-06-14 21:17:09'),(36,'home_show_banner','1','2026-06-14 19:35:55','2026-06-14 20:32:56'),(37,'home_show_articles','1','2026-06-14 19:35:55','2026-06-14 20:32:56'),(38,'home_show_stats','1','2026-06-14 19:35:55','2026-06-14 20:32:56'),(39,'home_show_features','1','2026-06-14 19:35:55','2026-06-14 20:32:56'),(40,'home_show_search','1','2026-06-14 19:35:55','2026-06-14 20:32:56'),(41,'home_articles_count','6','2026-06-14 19:35:55','2026-06-14 19:35:55'),(42,'home_features_title','核心功能','2026-06-14 19:35:55','2026-06-14 20:33:35'),(43,'home_articles_title','帮助文章','2026-06-14 19:35:55','2026-06-14 20:33:35'),(44,'home_stats_title','站内数据','2026-06-14 19:35:55','2026-06-14 20:33:35'),(45,'site_primary_color','#3e2723','2026-06-14 19:35:55','2026-06-14 21:17:09'),(46,'site_accent_color','#c8962e','2026-06-14 19:35:55','2026-06-14 21:17:09'),(47,'home_about_title','关于族谱传承','2026-06-14 19:50:27','2026-06-14 21:16:40'),(48,'home_about_content','族谱传承是一个专业的数字化家谱管理平台，致力于用现代技术守护中华家族记忆。无论您是想追溯家族源流、记录先人事迹，还是编修电子族谱、传承优良家风，这里都是您的理想起点。平台支持在线创建家谱、智能编目排版、一键导出成书，让修谱不再繁琐，让传承触手可及。','2026-06-14 19:50:27','2026-06-14 21:16:40'),(49,'home_value1_title','传承','2026-06-14 19:50:27','2026-06-14 21:16:40'),(50,'home_value1_desc','记录家族历史，编修数字族谱，让先辈智慧代代相传','2026-06-14 19:50:27','2026-06-14 21:16:40'),(51,'home_value2_title','溯源','2026-06-14 19:50:27','2026-06-14 21:16:40'),(52,'home_value2_desc','探寻姓氏起源，追本溯源，了解家族的迁徙与发展','2026-06-14 19:50:27','2026-06-14 21:16:40'),(53,'home_value3_title','凝聚','2026-06-14 19:50:27','2026-06-14 21:16:40'),(54,'home_value3_desc','线上线下结合，凝聚宗亲力量，重塑家族纽带','2026-06-14 19:50:27','2026-06-14 21:16:40'),(55,'home_value4_title','创新','2026-06-14 19:50:27','2026-06-14 21:16:40'),(56,'home_value4_desc','数字化修谱新方式，智能排版一键成书，让传承更简单','2026-06-14 19:50:27','2026-06-14 21:16:40'),(57,'home_show_about','1','2026-06-14 19:50:27','2026-06-14 20:32:56'),(58,'home_show_values','1','2026-06-14 19:50:27','2026-06-14 20:32:56'),(59,'footer_qr_app','','2026-06-14 19:59:43','2026-06-14 19:59:43'),(60,'footer_qr_app_label','下载APP','2026-06-14 19:59:43','2026-06-14 19:59:43'),(61,'footer_qr_wechat','','2026-06-14 19:59:43','2026-06-14 19:59:43'),(62,'footer_qr_wechat_label','关注公众号','2026-06-14 19:59:43','2026-06-14 19:59:43'),(63